import{_ as a,c as t,o as i,ae as p}from"./chunks/framework.DiDWbMQc.js";const f=JSON.parse('{"title":"一、安装描述文件","description":"","frontmatter":{},"headers":[],"relativePath":"docs/mobile/ios.md","filePath":"docs/mobile/ios.md"}'),o={name:"docs/mobile/ios.md"};function s(c,e,r,n,d,l){return i(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="一、安装描述文件" tabindex="-1">一、安装描述文件 <a class="header-anchor" href="#一、安装描述文件" aria-label="Permalink to &quot;一、安装描述文件&quot;">​</a></h1><p>默认安装「有赞移动」 App 的情况下，手机是没有安装根证书的，这会导致抓包或者连接弹出错误，在使用的时候，应当安装根证书（类似 Charles 的操作)</p><p>你会看见界面如下</p><img src="https://img.yzcdn.cn/public_files/2018/11/16/5b81a436f10ed0dc78b9fa3b56e6dbb1.png" width="500"><p>点击红字，就会安装描述文件，一路点允许即可。</p><p>安装完后是这样的</p><img src="https://img.yzcdn.cn/public_files/2018/11/16/d02c1e243cfbf6ec4f51a2703660796a.png" width="500"><p>这个就是安装完成的状态。</p><h1 id="二、信任证书" tabindex="-1">二、信任证书 <a class="header-anchor" href="#二、信任证书" aria-label="Permalink to &quot;二、信任证书&quot;">​</a></h1><p>证书安装完成的时候，默认是不信任的，所以需要信任证书，信任证书的方式如下：</p><p>「设置」——「通用」——「关于本机」—— 拉到底部「证书信任设置」 —— 把 「zProxy」的开关打开 —— 完成</p><img src="https://img.yzcdn.cn/public_files/2018/11/16/2783949023fd2f9a6b1a730cfb54f204.png" width="500"><p>像这样，就完成了</p><p>好，开始enjoy抓包吧</p>',14)])])}const m=a(o,[["render",s]]);export{f as __pageData,m as default};
